# Last scanned for code smell: 2026-08-18 by Claude.
"""Wiki bundle: a whole wiki as per-page snapshots + a content-only manifest.

A **snapshot** (``snapshot.py``) is one page at a point in time. A **bundle** is
the wiki above it: a deterministic ZIP archive holding

* ``manifest.json`` — the format tag, the version pair (same gate as snapshots),
  an optional content-level ``label`` (the source wiki's display name), and the
  wiki's non-page content: the page list with its **hierarchy by slug**, order
  and starred flags, the custom elements, the templates (with the metadata
  schema a template may declare), and the image index;
* ``pages/<slug>.snapshot`` — one serialized :class:`~wiki_interchange.snapshot.Snapshot`
  envelope per page; and
* ``images/<sha256>`` — each distinct image blob, stored **once** for the whole
  wiki however many pages embed it.

This is the unit the Kahala ⇄ Waikiki round-trip moves when a *whole wiki* is
exported down or imported up (issue #3397 / K6, VerinFast/waikiki#57), sitting
one level above the per-page snapshot round-trip.

**Hierarchy travels by slug, never by id.** A page's integer id is local to the
side that minted it; the same page is a different number on each peer, so an id
that crossed would point at whatever page happened to hold that number over
there. ``parent_slug`` is the only portable spelling of "child of".

Security boundary — identical to the snapshot layer, one level up:

* **Content-only, tenant-neutral.** The manifest carries no ``tenant_id`` /
  ``wiki_id`` / membership / permissions — :func:`assert_bundle_content_only`
  fails closed (:class:`~wiki_interchange.errors.ServerFieldLeakError`) if a
  server-only key appears anywhere in it, exactly like ``assert_content_only``
  guards a page doc. The wiki a bundle lands in is re-attached from *server*
  context on import-up (Kahala's job), never read from the payload.
* **No derived data.** There is no channel for RAG chunks or embeddings at any
  level of the container; they are regenerated by the importing side.
* **Version-gated.** The manifest carries ``spec_version`` + ``yjs_protocol`` and
  every embedded page snapshot carries its own pair; both are run through
  :func:`~wiki_interchange.version.check_compatible` on unpack, so an
  incompatible bundle is rejected, never merged.
* **No path traversal.** Page files are addressed by ``pages/<slug>.snapshot``
  and blobs by ``images/<sha256>``, with both re-validated on unpack (no ``/``,
  no ``..``), so a hostile archive cannot write outside its namespace (zip-slip).
* **Content-addressed blobs.** A blob's member name *is* its hash claim, and the
  bytes are re-hashed on unpack — substituted bytes are refused rather than
  handed to the importer under a trusted digest.

What is deliberately **not** duplicated here: a page's **tags** already live in
its Y.Doc (the ``tags`` root, mirrored in the markdown frontmatter), so the
bundle carries them through the page snapshot rather than in a second list that
could disagree with the first.

Determinism: given the same pages, sections and label, :func:`pack_bundle`
produces byte-identical archive output (sorted entries, fixed ZIP metadata). The
snapshot bytes themselves still vary run-to-run — a Yjs update embeds a random
client id — so this is reproducibility *of the container given its inputs*, not
of a fresh export of the same live page.

Streaming: a real wiki is hundreds of pages and tens of megabytes, so the pack
and unpack entry points work against a **file object** and touch one page at a
time (:func:`pack_bundle_into` here,
:class:`~wiki_interchange.bundle_reader.BundleReader` next door). The
``bytes``-in / ``bytes``-out helpers (:func:`pack_bundle`,
:func:`~wiki_interchange.bundle_reader.unpack_bundle`) are thin wrappers for
callers small enough not to care.

This module owns the records, the guards and the **write** side; reading a bundle
back lives in :mod:`wiki_interchange.bundle_reader`.
"""

from __future__ import annotations

import hashlib
import hmac
import io
import json
import re
import zipfile
from collections.abc import Iterable
from dataclasses import dataclass, field
from typing import IO, Any

from .errors import MalformedEnvelopeError, ServerFieldLeakError
from .schema import SERVER_ONLY_FIELD_NAMES
from .snapshot import Snapshot
from .version import WIKI_ENVELOPE_SPEC, YJS_SYNC_PROTOCOL_VERSION

FORMAT_BUNDLE = "good-place.wiki-interchange/bundle"

MANIFEST_NAME = "manifest.json"
_PAGE_PREFIX = "pages/"
_PAGE_SUFFIX = ".snapshot"
_IMAGE_PREFIX = "images/"

# A slug that is safe to interpolate into an archive member name: no path
# separators, no parent-dir escapes. Waikiki/Kahala slugs are ``[a-z0-9-]``; we
# accept a slightly wider set but reject anything that could traverse.
_SAFE_SLUG = re.compile(r"^[A-Za-z0-9._-]+$")
_SHA256 = re.compile(r"^[0-9a-f]{64}$")


# --- Records ------------------------------------------------------------------


@dataclass(frozen=True)
class BundlePage:
    """One page inside a bundle: its place in the wiki + a serialized snapshot.

    ``snapshot`` is the raw bytes of a :meth:`Snapshot.serialize` envelope — the
    same payload the per-page round-trip ships. Its Y.Doc state is carried
    verbatim; only the non-CRDT image sidecar is relocated (see
    :func:`pack_bundle_into`) and it is restored on the way out.

    ``parent_slug`` names the parent **by slug**: integer ids are local to one
    side and cannot travel. ``sort_order`` is the wiki's manual ordering
    (``None`` = unordered) and ``starred`` the favourite flag.
    """

    slug: str
    snapshot: bytes
    title: str | None = None
    parent_slug: str | None = None
    sort_order: int | None = None
    starred: bool = False


@dataclass(frozen=True)
class BundleElement:
    """A custom element definition (the ``\\`\\`\\`<slug>`` fenced-block kind)."""

    slug: str
    name: str
    fields: list[dict[str, Any]] = field(default_factory=list)
    html: str = ""
    css: str = ""
    js: str = ""


@dataclass(frozen=True)
class BundleTemplate:
    """A page template, including the metadata schema it may declare.

    ``meta_schema`` is the template's ``name[*]: type`` declaration, authored as
    text so what a human wrote round-trips verbatim; empty means the template
    constrains nothing.
    """

    name: str
    markdown: str = ""
    meta_schema: str = ""


@dataclass(frozen=True)
class BundleImage:
    """One distinct image blob, shared across every page that embeds it.

    ``image_ids`` lists the source side's local ids that resolved to these bytes,
    so an importer can rewrite ``/image/<id>`` references after re-homing the
    blob once. Like :class:`~wiki_interchange.snapshot.ImageRef` it is
    tenant-neutral: a content hash and media metadata, never a bucket path.
    """

    sha256: str
    media_type: str
    image_ids: list[str] = field(default_factory=list)
    filename: str | None = None
    byte_size: int | None = None
    data: bytes | None = None


# --- Guards -------------------------------------------------------------------


def _collect_keys(obj: Any) -> set[str]:
    """Every mapping key that appears anywhere in a plain-Python structure."""
    found: set[str] = set()
    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(key, str):
                found.add(key)
            found |= _collect_keys(value)
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            found |= _collect_keys(item)
    return found


def assert_bundle_content_only(manifest: dict[str, Any]) -> None:
    """Raise :class:`ServerFieldLeakError` if the manifest carries a server key.

    The bundle-level mirror of
    :func:`~wiki_interchange.schema.assert_content_only`: a wiki bundle is
    content only, so ``tenant_id`` / ``wiki_id`` / membership / permissions must
    never ride in the manifest — including inside the element, template and image
    sections, which this walks recursively. Compared case-folded against
    :data:`~wiki_interchange.schema.SERVER_ONLY_FIELD_NAMES`.
    """
    leaked = {k for k in _collect_keys(manifest) if k.casefold() in SERVER_ONLY_FIELD_NAMES}
    if leaked:
        raise ServerFieldLeakError(
            "server-only identity/authz fields must not appear in a wiki bundle "
            f"manifest: {sorted(leaked)}"
        )


def validate_slug(slug: str) -> str:
    """A page slug that is safe as an archive member name (shared with the reader)."""
    if not isinstance(slug, str) or not _SAFE_SLUG.match(slug) or slug in (".", ".."):
        raise MalformedEnvelopeError(f"unsafe or missing page slug in bundle: {slug!r}")
    return slug


def validate_hash(sha256: str) -> str:
    """A blob digest that is safe as an archive member name (shared with the reader)."""
    if not isinstance(sha256, str) or not _SHA256.match(sha256):
        raise MalformedEnvelopeError(f"image is not addressed by a sha256 digest: {sha256!r}")
    return sha256


def page_member(slug: str) -> str:
    return f"{_PAGE_PREFIX}{slug}{_PAGE_SUFFIX}"


def image_member(sha256: str) -> str:
    return f"{_IMAGE_PREFIX}{sha256}"


# --- Packing ------------------------------------------------------------------


def _write(archive: zipfile.ZipFile, name: str, data: bytes) -> None:
    """Add one entry with fixed metadata so the archive bytes are deterministic."""
    info = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
    info.compress_type = zipfile.ZIP_DEFLATED
    info.external_attr = 0o644 << 16
    archive.writestr(info, data)


def _page_entry(page: BundlePage, slug: str) -> dict[str, Any]:
    entry: dict[str, Any] = {"slug": slug}
    if page.title is not None:
        entry["title"] = page.title
    if page.parent_slug is not None:
        entry["parent_slug"] = validate_slug(page.parent_slug)
    if page.sort_order is not None:
        entry["sort_order"] = int(page.sort_order)
    if page.starred:
        entry["starred"] = True
    return entry


def _element_entry(element: BundleElement) -> dict[str, Any]:
    return {
        "slug": element.slug,
        "name": element.name,
        "fields": list(element.fields or []),
        "html": element.html,
        "css": element.css,
        "js": element.js,
    }


def _template_entry(template: BundleTemplate) -> dict[str, Any]:
    return {
        "name": template.name,
        "markdown": template.markdown,
        "meta_schema": template.meta_schema,
    }


def _image_entry(image: BundleImage) -> dict[str, Any]:
    entry: dict[str, Any] = {
        "sha256": image.sha256,
        "media_type": image.media_type,
        "image_ids": list(image.image_ids),
    }
    if image.filename is not None:
        entry["filename"] = image.filename
    if image.byte_size is not None:
        entry["byte_size"] = image.byte_size
    return entry


def _hoist_images(snapshot: bytes, blobs: dict[str, BundleImage]) -> bytes:
    """Move a page snapshot's inline blobs into the shared image index.

    Returns the snapshot re-serialized with its sidecar refs kept but their bytes
    dropped, recording each distinct blob in ``blobs`` keyed by hash. A logo
    embedded on two hundred pages is stored once; unpacking puts it back on every
    page that referenced it, so a consumer sees the same snapshot it would have
    received unbundled. The page's Y.Doc state is never touched.
    """
    snap = Snapshot.deserialize(snapshot)  # runs the version gate; rejects non-snapshots
    if not any(img.data is not None for img in snap.images):
        return snapshot  # nothing to hoist: keep the caller's bytes verbatim
    for img in snap.images:
        if img.data is None:
            continue
        digest = hashlib.sha256(img.data).hexdigest()
        if img.sha256 and not hmac.compare_digest(digest, str(img.sha256).lower()):
            raise MalformedEnvelopeError(
                f"image {img.image_id}: inline blob does not match its sha256 "
                f"(claimed {str(img.sha256)[:12]}…, actual {digest[:12]}…)"
            )
        known = blobs.get(digest)
        blobs[digest] = BundleImage(
            sha256=digest,
            media_type=img.media_type or (known.media_type if known else ""),
            image_ids=sorted({*(known.image_ids if known else []), str(img.image_id)}),
            filename=img.filename or (known.filename if known else None),
            byte_size=len(img.data),
            data=img.data,
        )
    return snap.without_blobs().serialize()


def pack_bundle_into(
    dest: IO[bytes],
    pages: Iterable[BundlePage],
    *,
    elements: Iterable[BundleElement] = (),
    templates: Iterable[BundleTemplate] = (),
    label: str | None = None,
) -> None:
    """Stream a wiki bundle into ``dest`` (a writable, seekable binary file).

    Pages are consumed one at a time and written as they arrive, so a wiki far
    larger than memory can be exported; only the manifest — page metadata, the
    element/template sections and the image index — is held, and it is written
    last. Feed ``pages`` in slug order for byte-stable output;
    :func:`pack_bundle` does that for you.

    Each page's ``snapshot`` is validated as a real :class:`Snapshot` envelope
    (which runs the version gate), its inline image blobs are hoisted into the
    shared image area, and the manifest is checked content-only. Fails closed
    (:class:`MalformedEnvelopeError` / :class:`ServerFieldLeakError`) rather than
    ship a malformed or identity-bearing bundle.
    """
    seen: set[str] = set()
    parents: set[str] = set()
    manifest_pages: list[dict[str, Any]] = []
    blobs: dict[str, BundleImage] = {}

    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED) as archive:
        for page in pages:
            slug = validate_slug(page.slug)
            if slug in seen:
                raise MalformedEnvelopeError(f"duplicate page slug in bundle: {slug!r}")
            seen.add(slug)
            entry = _page_entry(page, slug)
            if "parent_slug" in entry:
                parents.add(entry["parent_slug"])
            manifest_pages.append(entry)
            _write(archive, page_member(slug), _hoist_images(page.snapshot, blobs))

        dangling = parents - seen
        if dangling:
            raise MalformedEnvelopeError(
                "bundle names parent pages it does not contain — a whole-wiki "
                f"bundle must be self-contained: {sorted(dangling)}"
            )

        for digest in sorted(blobs):
            _write(archive, image_member(digest), blobs[digest].data or b"")

        manifest: dict[str, Any] = {
            "format": FORMAT_BUNDLE,
            "spec_version": WIKI_ENVELOPE_SPEC,
            "yjs_protocol": YJS_SYNC_PROTOCOL_VERSION,
            "pages": sorted(manifest_pages, key=lambda e: e["slug"]),
            "elements": [_element_entry(e) for e in sorted(elements, key=lambda e: e.slug)],
            "templates": [_template_entry(t) for t in sorted(templates, key=lambda t: t.name)],
            "images": [_image_entry(blobs[d]) for d in sorted(blobs)],
        }
        if label is not None:
            manifest["label"] = label
        assert_bundle_content_only(manifest)
        _write(
            archive,
            MANIFEST_NAME,
            json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode("utf-8"),
        )


def pack_bundle(
    pages: Iterable[BundlePage],
    *,
    elements: Iterable[BundleElement] = (),
    templates: Iterable[BundleTemplate] = (),
    label: str | None = None,
) -> bytes:
    """Pack a whole wiki into a deterministic bundle archive, in memory.

    The ``bytes``-returning wrapper around :func:`pack_bundle_into`: entries are
    normalized to slug order so equal inputs yield equal bytes. Prefer the
    streaming form for a wiki of real size.
    """
    buf = io.BytesIO()
    pack_bundle_into(
        buf,
        sorted(pages, key=lambda p: p.slug),
        elements=elements,
        templates=templates,
        label=label,
    )
    return buf.getvalue()
